2	import 'package:flutter/services.dart';
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	import 'package:mocktail/mocktail.dart';
6	
7	import 'package:cerne/core/di/injection_container.dart';
8	import 'package:cerne/features/auth/domain/entities/authenticated_user.dart';
9	import 'package:cerne/features/auth/domain/repositories/auth_repository.dart';
10	import 'package:cerne/main.dart';
11	
12	class MockAuthRepository extends Mock implements AuthRepository {}
13	
14	/// Proves the one real production composition root — `CerneApp` resolving
15	/// `sl<AuthCubit>()` and wiring `onAuthenticated` to
16	/// `Navigator.pushReplacement` — actually works end to end (code review of
17	/// story-1-3-account-creation-and-login). Every other test either stops at
18	/// DI registration (`bootstrap_integration_test.dart`) or supplies its own
19	/// `AuthCubit`/`onAuthenticated` (`auth_screen_test.dart`), so neither
20	/// exercises `main.dart`'s own wiring.
21	void main() {
22	  TestWidgetsFlutterBinding.ensureInitialized();
23	
24	  const secureStorageChannel = MethodChannel(
25	    'plugins.it_nomads.com/flutter_secure_storage',
26	  );
27	  final fakeNativeStorage = <String, String>{};
28	
29	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
30	    final args = call.arguments as Map<dynamic, dynamic>;
31	    switch (call.method) {
32	      case 'write':
33	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
34	        return null;
35	      case 'read':
36	        return fakeNativeStorage[args['key'] as String];
37	      case 'delete':
38	        fakeNativeStorage.remove(args['key'] as String);
39	        return null;
40	      case 'containsKey':
41	        return fakeNativeStorage.containsKey(args['key'] as String);
42	      default:
43	        return null;
44	    }
45	  }
46	
